package thaumcraft.world.eldritch;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.animal.Cow;
import net.minecraft.world.effect.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.*;
import net.minecraftforge.gametest.*;
import thaumcraft.catalog.entities.VisualEntitiesModule;

@GameTestHolder("thaumcraft") @PrefixGameTestTemplate(false)
public final class EldritchGameTests {
    private EldritchGameTests(){}
    private static final class Arena implements AutoCloseable {
        final GameTestHelper helper;final BlockPos p;final Map<BlockPos,BlockState> saved=new LinkedHashMap<>();final List<Entity> actors=new ArrayList<>();
        Arena(GameTestHelper h){helper=h;BlockPos origin=h.absolutePos(new BlockPos(3,0,3));p=new BlockPos(origin.getX(),250,origin.getZ());for(int x=(p.getX()-8)>>4;x<=(p.getX()+8)>>4;x++)for(int z=(p.getZ()-8)>>4;z<=(p.getZ()+8)>>4;z++)h.getLevel().getChunk(x,z);for(BlockPos at:BlockPos.betweenClosed(p.offset(-8,-1,-8),p.offset(8,5,8))){at=at.immutable();saved.put(at,h.getLevel().getBlockState(at));h.getLevel().setBlock(at,at.getY()==249?Blocks.BEDROCK.defaultBlockState():Blocks.AIR.defaultBlockState(),3);}}
        <T extends Entity>T keep(T entity){actors.add(entity);entity.setPos(Vec3.atBottomCenterOf(p));return entity;}
        <T extends Entity>T mob(String id,Class<T> type){return keep(type.cast(VisualEntitiesModule.LIVING.get(id).get().create(helper.getLevel())));}
        @Override public void close(){for(Entity entity:actors)entity.discard();boolean old=helper.getLevel().restoringBlockSnapshots;helper.getLevel().restoringBlockSnapshots=true;try{var entries=new ArrayList<>(saved.entrySet());Collections.reverse(entries);for(var entry:entries)helper.getLevel().setBlock(entry.getKey(),entry.getValue(),3);}finally{helper.getLevel().restoringBlockSnapshots=old;}for(var e:helper.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(p.offset(-9,-2,-9),p.offset(9,7,9))))e.discard();}
    }
    @GameTest(template="empty") public static void crabHelmetBreaksAtHalfAndPoisonCannotApply(GameTestHelper h){try(var arena=new Arena(h)){var crab=arena.mob("eldritch_crab",EldritchCrabEntity.class);crab.setHelm(true);h.assertTrue(crab.getMaxHealth()==20&&crab.getArmorValue()==5&&crab.getAttributeValue(Attributes.ATTACK_DAMAGE)==4,"Original crab stats missing");h.assertTrue(!crab.addEffect(new MobEffectInstance(MobEffects.POISON,100)),"Crab lost arthropod poison immunity");crab.setHealth(11);crab.hurt(crab.damageSources().generic(),4);h.assertTrue(!crab.hasHelm()&&crab.getArmorValue()==0&&crab.getAttributeValue(Attributes.MOVEMENT_SPEED)==.3,"Helmet threshold did not release armor/speed");var tag=new CompoundTag();crab.addAdditionalSaveData(tag);var restored=arena.mob("eldritch_crab",EldritchCrabEntity.class);restored.readAdditionalSaveData(tag);h.assertTrue(!restored.hasHelm()&&restored.getMobType()==MobType.ARTHROPOD&&!restored.isNoAi(),"Crab save became catalogue shell");}h.succeed();}
    @GameTest(template="empty") public static void inhabitedDeathReplacesExactlyOnceWithoutZombieLoot(GameTestHelper h){try(var arena=new Arena(h)){var zombie=arena.keep(EldritchModule.INHABITED_ZOMBIE.get().create(h.getLevel()));zombie.setNoAi(true);h.getLevel().addFreshEntity(zombie);zombie.hurt(zombie.damageSources().generic(),100);zombie.tick();var children=h.getLevel().getEntitiesOfClass(EldritchCrabEntity.class,new AABB(arena.p.offset(-2,-1,-2),arena.p.offset(2,5,2)));h.assertTrue(zombie.isRemoved()&&children.size()==1&&children.get(0).hasHelm(),"Inhabited zombie did not release one helmeted crab immediately");arena.actors.addAll(children);zombie.tickDeath();h.assertTrue(h.getLevel().getEntitiesOfClass(EldritchCrabEntity.class,new AABB(arena.p.offset(-2,-1,-2),arena.p.offset(2,5,2))).size()==1,"Repeated death callback duplicated crab");h.assertTrue(h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,zombie.getBoundingBox().inflate(3)).isEmpty(),"Original inhibited Zombie death generated flesh/equipment loot");}h.succeed();}
    @GameTest(template="empty") public static void nativeBossCapEnrageAndHomeSurviveOriginalPersistenceRules(GameTestHelper h){try(var arena=new Arena(h)){var boss=arena.mob("eldritch_warden",EldritchWardenEntity.class);boss.setAbsorptionAmount(300);boss.hurt(boss.damageSources().generic(),80);h.assertTrue(boss.anger()==200&&boss.hasEffect(MobEffects.REGENERATION)&&boss.getAbsorptionAmount()>=265&&boss.getMaxHealth()==400,"Boss lost 35 cap/enrage or gained ordinary champion HP");boss.restrictTo(arena.p,24);var tag=new CompoundTag();boss.addAdditionalSaveData(tag);var restored=arena.mob("eldritch_warden",EldritchWardenEntity.class);restored.readAdditionalSaveData(tag);h.assertTrue(restored.hasRestriction()&&restored.getRestrictCenter().equals(arena.p)&&restored.anger()==0&&restored.spawnTimer()==0,"Original home or transient boss state persistence changed");}h.succeed();}
    @GameTest(template="empty") public static void wardenSpawnFieldAndOnceOnlyFrenzyAreDistinct(GameTestHelper h){try(var arena=new Arena(h)){var boss=arena.mob("eldritch_warden",EldritchWardenEntity.class);boss.finalizeSpawn(h.getLevel(),h.getLevel().getCurrentDifficultyAt(arena.p),MobSpawnType.MOB_SUMMONED,null,null);h.assertTrue(boss.spawnTimer()==150&&boss.getAbsorptionAmount()==264&&!boss.hurt(boss.damageSources().generic(),10),"Original Warden spawn shield/invulnerability changed");var active=arena.mob("eldritch_warden",EldritchWardenEntity.class);active.setAbsorptionAmount(1);h.assertTrue(active.hurt(active.damageSources().generic(),10)&&active.fieldFrenzyCounter()==150&&active.hasUsedFieldFrenzy()&&!active.hurt(active.damageSources().generic(),10),"Broken field failed to enter once-only invulnerable frenzy");h.assertTrue(!active.hurt(active.damageSources().wither(),10),"Warden accepted Wither");}h.succeed();}
    @GameTest(template="empty") public static void golemRawLethalHitStartsHeadlessPhaseBeforeDamageCap(GameTestHelper h){try(var arena=new Arena(h)){var golem=arena.mob("eldritch_golem",EldritchGolemEntity.class);golem.setHealth(20);h.assertTrue(!golem.hurt(golem.damageSources().generic(),21)&&golem.headless()&&golem.spawnTimer()==100&&golem.getHealth()==20,"Golem lost original raw lethal phase transition");golem.setNoAi(true);golem.setNoGravity(true);for(int tick=0;tick<150;tick++)golem.tick();h.assertTrue(golem.beamCharge()==150&&!golem.chargingBeam()&&golem.getHealth()>20,"Headless original magazine did not recharge to150/heal");var tag=new CompoundTag();golem.addAdditionalSaveData(tag);var restored=arena.mob("eldritch_golem",EldritchGolemEntity.class);restored.readAdditionalSaveData(tag);h.assertTrue(restored.headless()&&restored.beamCharge()==0&&restored.spawnTimer()==0,"Headless save lost phase or invented persisted magazine");}h.succeed();}
    @GameTest(template="empty") public static void leaderSupportsCubeCornerCultistAndCastsNativeRedSeekingOrb(GameTestHelper h){try(var arena=new Arena(h)){var leader=arena.mob("cultist_leader",CultistLeaderEntity.class);var ally=arena.mob("cultist_knight",thaumcraft.world.crimson.CultistEntity.class);ally.setPos(leader.position().add(7,0,7));ally.setNoAi(true);h.getLevel().addFreshEntity(ally);leader.tick();h.assertTrue(ally.hasEffect(MobEffects.REGENERATION)&&ally.getEffect(MobEffects.REGENERATION).getAmplifier()==1,"Original cuboid support was replaced by a radius");Cow target=arena.keep(EntityType.COW.create(h.getLevel()));target.setPos(leader.position().add(5,0,0));target.setNoAi(true);h.getLevel().addFreshEntity(target);leader.performRangedAttack(target,1);var orbs=h.getLevel().getEntitiesOfClass(thaumcraft.golemancy.entity.GolemOrbEntity.class,leader.getBoundingBox().inflate(3),orb->orb.getOwner()==leader);arena.actors.addAll(orbs);h.assertTrue(orbs.size()==1&&orbs.get(0).red()&&orbs.get(0).target()==target&&leader.isAlliedTo(ally),"Leader did not reuse actual red native seeking orb/team");}h.succeed();}
    @GameTest(template="empty") public static void greaterPortalRaisesFourFacingBannersOnOriginalFortiethTick(GameTestHelper h){try(var arena=new Arena(h)){var portal=arena.mob("cultist_portal_greater",GreaterCultistPortalEntity.class);for(int tick=0;tick<40;tick++)portal.tick();int count=0;for(var direction:net.minecraft.core.Direction.Plane.HORIZONTAL){BlockPos at=new BlockPos((int)portal.getX()-direction.getStepX()*6,(int)portal.getY(),(int)portal.getZ()+direction.getStepZ()*6);if(h.getLevel().getBlockState(at).is(thaumcraft.catalog.blocks.CatalogBlocks.block("banner_crimson_cult")))count++;}h.assertTrue(portal.stageCounter()==160&&count==4&&portal.getMaxHealth()==500,"Greater encounter intro did not create original four banners/timing");}h.succeed();}
    @GameTest(template="empty") public static void greaterPortalOriginalSavedStageSpawnsLeaderAndLateMinionDebitsHealth(GameTestHelper h){try(var arena=new Arena(h)){var portal=arena.mob("cultist_portal_greater",GreaterCultistPortalEntity.class);var tag=new CompoundTag();portal.addAdditionalSaveData(tag);tag.putInt("stage",13);portal.readAdditionalSaveData(tag);h.assertTrue(portal.stage()==13&&portal.stageCounter()==200,"Portal persisted counter or discarded original stage");var boss=portal.spawnBoss();h.assertTrue(boss!=null&&boss.hasRestriction()&&boss.getRestrictRadius()==32,"Greater portal did not spawn actual home-bound praetor");arena.actors.add(boss);var minion=portal.spawnMinion();h.assertTrue(minion!=null&&portal.getHealth()>=491&&portal.getHealth()<=495&&minion.cultHome().equals(portal.blockPosition()),"Late wave lost finite-health debit or home");arena.actors.add(minion);}h.succeed();}
    @GameTest(template="empty") public static void pearlRewardUsesOriginalSpecialItemGravityExplosionGuardAndCapturedOwnership(GameTestHelper h){try(var arena=new Arena(h)){
        var owner=arena.mob("eldritch_warden",EldritchWardenEntity.class);var captured=new ArrayList<net.minecraft.world.entity.item.ItemEntity>();var previous=owner.captureDrops(captured);
        try{owner.dropCustomDeathLoot(owner.damageSources().generic(),0,true);}finally{owner.captureDrops(previous);}
        var pearls=captured.stream().filter(e->e.getItem().is(thaumcraft.catalog.CatalogModule.stack("primordial_pearl").getItem())).toList();h.assertTrue(captured.size()==2&&pearls.size()==1&&pearls.get(0) instanceof thaumcraft.auromancy.remaining.FocusExchangeItemEntity,"Boss pearl became an ordinary item or escaped Forge captured-drop ownership");
        var reward=(thaumcraft.auromancy.remaining.FocusExchangeItemEntity)pearls.get(0);arena.actors.addAll(captured);h.assertTrue(reward.getType()==EldritchModule.SPECIAL_ITEM.get()&&h.getLevel().getEntity(reward.getId())==null&&reward.getDeltaMovement().equals(new Vec3(0,.10000000149011612,0))&&reward.getY()==owner.getY()+owner.getBbHeight()/2&&reward.hasPickUpDelay(),"Special drop lost original ID/motion/height/default delay or was inserted twice");
        var tag=new CompoundTag();reward.saveWithoutId(tag);var restored=arena.keep(EldritchModule.SPECIAL_ITEM.get().create(h.getLevel()));restored.load(tag);h.assertTrue(restored.getItem().getDamageValue()==0&&restored.getItem().getCount()==1&&restored.hasPickUpDelay()&&restored.getDeltaMovement().equals(reward.getDeltaMovement()),"Special physical pearl save lost stack, delay or motion");
        double y=restored.getY();restored.tick();restored.tick();h.assertTrue(restored.getY()>y&&restored.getDeltaMovement().y>0&&restored.getDeltaMovement().y<.1,"Special item lost original compensated gravity/positive-Y damping");
        var explosion=new net.minecraft.world.damagesource.DamageSource(h.getLevel().registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.DAMAGE_TYPE).getHolderOrThrow(net.minecraft.world.damagesource.DamageTypes.EXPLOSION));h.assertTrue(!restored.hurt(explosion,100)&&!restored.isRemoved(),"Special boss pearl lost original explosion immunity");
    }h.succeed();}
}
